# Generated by manage.py generate_test_cases.
from django.core.exceptions import ValidationError
from django.utils import timezone

from bloomerp.communication.builtins.emails.email_providers import EmailProvider
from bloomerp.models.audit.activity_log import ActivityLog, ActivityLogAction
from bloomerp.models.communication.email_account import EmailAccount
from bloomerp.services.activity_log_services import ActivityLogManager
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)


class TestEmailAccountModel(BloomerpModelTestCase):
    model = EmailAccount

    def get_test_scenarios(self) -> list[ModelScenario[EmailAccount]]:
        """Verify provider validation and persistence of optional outgoing settings."""
        return [
            ModelScenario(
                name="Repeated successful syncs retain creation but add no bookkeeping logs",
                create_args={"email_address": "quiet-sync@example.com"},
                post_create=self.run_repeated_successful_syncs,
                create_validators=self.has_only_create_log,
                delete_validators=self.has_create_and_delete_logs,
            ),
            ModelScenario(
                name="Mixed bookkeeping and configuration edits retain the complete audit diff",
                create_args={"email_address": "config-audit@example.com"},
                update_args={"name": "New label", "next_sync_at": timezone.now()},
                update_validators=self.has_configuration_change_log,
            ),
            ModelScenario(
                name="Sync errors remain visible despite bookkeeping changes",
                create_args={"email_address": "error-audit@example.com"},
                update_args={"last_sync_error": "Connection refused", "next_sync_at": timezone.now()},
                update_validators=self.has_sync_error_change_log,
            ),
            ModelScenario(
                name="Clearing an existing sync error remains a useful audit entry",
                create_args={"email_address": "recovery-audit@example.com", "last_sync_error": "Connection refused"},
                update_args={"last_sync_error": "", "next_sync_at": timezone.now()},
                update_validators=self.has_sync_error_change_log,
            ),
            ModelScenario(
                name="Legacy mailbox lists become editable mappings",
                create_args={"email_address": "mapping@example.com", "mailboxes": ["INBOX", "Sent", "Archive"]},
                create_validators=self.default_mailboxes_are_mapped,
                update_args={"mailboxes": {"INBOX": {"label": "Customer mail", "main_folder": True, "color": "#2563eb"}}},
                update_validators=self.custom_mailbox_is_saved,
            ),
            ModelScenario(
                name="Envelope sender defaults blank and can be configured",
                create_args={
                    "email_address": "alias@example.com",
                    "imap_host": "imap.example.com",
                    "imap_port": 993,
                    "smtp_host": "smtp.example.com",
                    "smtp_port": 587,
                },
                create_validators=self.envelope_sender_is_blank,
                update_args={"smtp_envelope_sender": "primary@example.com"},
                update_validators=self.envelope_sender_is_primary,
            ),
            ModelScenario(
                name="Sent-copy saving defaults off and can be enabled",
                create_args={
                    "email_address": "sent-copy@example.com",
                    "imap_host": "imap.example.com",
                    "imap_port": 993,
                    "smtp_host": "smtp.example.com",
                    "smtp_port": 587,
                },
                create_validators=self.sent_copy_is_disabled,
                update_args={"save_sent_emails": True},
                update_validators=self.sent_copy_is_enabled,
            ),
            ModelScenario(
                name="Email account validates provider-required fields",
                description=(
                    "UC: An IMAP account omits its server configuration.\n"
                    "Expected Result: Model validation identifies the required IMAP host."
                ),
                create_operation=self.validate_incomplete_imap_account,
                expected_exceptions=[
                    ExpectedModelException(
                        phase="create",
                        exception=ValidationError,
                        message_regex="imap_host",
                    )
                ],
            )
        ]

    @staticmethod
    def envelope_sender_is_blank(account: EmailAccount) -> bool:
        """Check backwards-compatible empty envelope configuration after persistence."""
        return account.smtp_envelope_sender == ""

    @staticmethod
    def envelope_sender_is_primary(account: EmailAccount) -> bool:
        """Check that the explicit primary envelope persists without changing the alias."""
        return account.smtp_envelope_sender == "primary@example.com" and account.email_address == "alias@example.com"

    @staticmethod
    def validate_incomplete_imap_account():
        account = EmailAccount(
            provider=EmailProvider.IMAP.value.key,
            name="Incomplete inbox",
            email_address="incomplete@example.com",
        )
        account.full_clean()
        return account

    @staticmethod
    def sent_copy_is_disabled(account: EmailAccount) -> bool:
        """Check that existing and new accounts do not save extra Sent copies by default."""
        return account.save_sent_emails is False

    @staticmethod
    def sent_copy_is_enabled(account: EmailAccount) -> bool:
        """Check that opting into Sent-copy saving persists on the account."""
        return account.save_sent_emails is True

    @staticmethod
    def default_mailboxes_are_mapped(account: EmailAccount) -> bool:
        """Check persisted migration-compatible input receives labels and role defaults."""
        return account.mailboxes["INBOX"]["main_folder"] and account.mailboxes["Sent"]["sent_folder"] and account.mailboxes["Archive"]["label"] == "Archive"

    @staticmethod
    def custom_mailbox_is_saved(account: EmailAccount) -> bool:
        """Check user labels and colors survive model persistence."""
        return account.mailboxes["INBOX"]["label"] == "Customer mail" and account.mailboxes["INBOX"]["color"] == "#2563eb"

    def run_repeated_successful_syncs(self, account: EmailAccount) -> None:
        """Exercise the same partial save as successful polling, twice in succession."""
        self.deleted_account_id = str(account.pk)
        for _ in range(2):
            account.last_sync_finished_at = timezone.now()
            account.next_sync_at = timezone.now()
            account.sync_locked_until = None
            account.last_sync_error = ""
            account.save(update_fields=[
                "last_sync_finished_at", "last_sync_error", "next_sync_at",
                "sync_locked_until", "datetime_updated",
            ])

    @staticmethod
    def has_only_create_log(account: EmailAccount) -> bool:
        """Bookkeeping-only saves preserve the original creation event."""
        logs = ActivityLogManager(account).get_for_object()
        return list(logs.values_list("action", flat=True)) == [ActivityLogAction.CREATE]

    def has_create_and_delete_logs(self, account: EmailAccount) -> bool:
        """The ignored-field gate never suppresses deletion."""
        logs = ActivityLog.objects.filter(
            content_type=ActivityLogManager(account).get_content_type(),
            object_id=self.deleted_account_id,
        )
        return set(logs.values_list("action", flat=True)) == {ActivityLogAction.CREATE, ActivityLogAction.DELETE}

    @staticmethod
    def has_configuration_change_log(account: EmailAccount) -> bool:
        """A useful field keeps the whole diff rather than removing ignored details."""
        log = ActivityLogManager(account).get_for_object().get(action=ActivityLogAction.CHANGE)
        return {change["field"] for change in log.payload} >= {"name", "next_sync_at"}

    @staticmethod
    def has_sync_error_change_log(account: EmailAccount) -> bool:
        """Both error introduction and recovery survive the sync-only gate."""
        log = ActivityLogManager(account).get_for_object().get(action=ActivityLogAction.CHANGE)
        return "last_sync_error" in {change["field"] for change in log.payload}
